import React, { useEffect, useState } from 'react';
import StatCard from '../components/StatCard';
import QuickAction from '../components/QuickAction';
import ActivityFeed from '../components/ActivityFeed';

export default function DashboardPage() {
  const [stats, setStats] = useState({ dashboards: 0, bookmarks: 0, uploads: 0, reports: 0 });
  const [activities, setActivities] = useState([]);

  useEffect(() => {
    // Replace with Amplify API call later
    setStats({ dashboards: 12, bookmarks: 28, uploads: 5, reports: 34 });
    setActivities([
      { id: 1, text: 'Created dashboard “Mental Health Trends Q1”' },
      { id: 2, text: 'Uploaded “Mental_Health_Survey_Data.xlsx”' },
    ]);
  }, []);

  return (
    <div className="dashboard-container p-6 space-y-6">
      {/* Top Welcome Card */}
      <div className="flex justify-between items-center bg-white rounded-xl p-6 shadow">
        <div>
          <h2 className="text-xl font-semibold">Welcome back, Sarah!</h2>
          <p className="text-sm text-gray-500">Research Analyst • Here's what's happening in your workspace</p>
        </div>
        <button className="bg-blue-600 text-white text-sm px-4 py-2 rounded-lg hover:bg-blue-700 transition">
          + New Project
        </button>
      </div>

      {/* Stats Section */}
      <div className="grid grid-cols-4 gap-4">
        <StatCard label="My Dashboards" value={stats.dashboards} icon="📊" />
        <StatCard label="Bookmarked Datasets" value={stats.bookmarks} icon="🔖" />
        <StatCard label="Uploaded Files" value={stats.uploads} icon="📁" />
        <StatCard label="Generated Reports" value={stats.reports} icon="📄" />
      </div>

      {/* Quick Actions */}
      <div className="bg-white rounded-xl p-6 shadow">
        <h3 className="text-md font-medium mb-4">Quick Actions</h3>
        <div className="grid grid-cols-4 gap-4">
          <QuickAction label="Create Dashboard" icon="📊" />
          <QuickAction label="Upload CSV" icon="📤" />
          <QuickAction label="Browse Datasets" icon="🔍" />
          <QuickAction label="Generate Report" icon="📄" />
        </div>
      </div>

      {/* Activity + AI Search */}
      <div className="grid grid-cols-2 gap-6">
        <div className="bg-white rounded-xl p-6 shadow">
          <h3 className="text-md font-medium mb-4">Recent Activity</h3>
          <ActivityFeed activities={activities} />
        </div>
        <div className="bg-white rounded-xl p-6 shadow">
          <h3 className="text-md font-medium mb-4">AI Search</h3>
          <p className="text-sm text-gray-600 mb-2">AI search coming soon...</p>
          {/* You can plug in chat later */}
        </div>
      </div>
    </div>
  );
}
